--
-- Table structure for table `products`
--

DROP TABLE IF EXISTS `products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `products` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `price` decimal(10,2) DEFAULT '0.00',
  `cost_price` decimal(10,2) DEFAULT NULL,
  `category_id` int DEFAULT NULL,
  `size` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `color` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `quantity` int DEFAULT '0',
  `min_stock_alert` int DEFAULT '5',
  `status` enum('active','inactive','archived') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'active',
  `is_trending` tinyint(1) DEFAULT '0',
  `rating` decimal(3,2) DEFAULT '0.00',
  `total_views` int DEFAULT '0',
  `total_sold` int DEFAULT '0',
  `created_by` int DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `category_id` (`category_id`),
  KEY `created_by` (`created_by`),
  CONSTRAINT `products_ibfk_1` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `products_ibfk_2` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=99 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `products`
--

LOCK TABLES `products` WRITE;
/*!40000 ALTER TABLE `products` DISABLE KEYS */;
INSERT INTO `products` VALUES (48,'Tendenza Elegant Wide Leg Tailored Pant','Pant\r\nWide Leg\r\nCasual Wear\r\nFabric : Cotton\r\nFabric Composition : 80% Cotton, 20% Polyester\r\nHigh rise waist and a clean, streamlined trouser, these trousers offer a polished look that\'s perfect for both work and weekend styling. The rich burgundy hue adds a refined touch, making them a versatile staple for any modern wardrobe.\r\n\r\nFeatures\r\n\r\nTailored high rise waistband.\r\nStructured waistband with belt loops and tab detailed.\r\nFront zip fly with hook and bar closure.\r\nIdeal for office wear, business casual, smart casual, and evening outings.\r\nFit & Model Details: Regular Fit, Model Height 5\' 6\" wearing size M\r\n\r\nPlease bear in mind that the photo may be slightly different from the actual item in terms of colour due to lighting conditions or the display used to view',2490.00,1880.00,NULL,NULL,NULL,74,5,'archived',1,0.00,22,48,1,'2026-08-08 08:57:31','2026-08-08 08:57:31'),(49,'Tendenza Deep V Neck Maxi Dress','Dress\r\nMaxi\r\nV Neck\r\nCasual Wear\r\nMaterial :  Cotton\r\nMaterial Composition : 100% Cotton\r\nEffortlessly elegant and easy to wear, this paisley print maxi dress is designed to take you from daytime outings to evening occasions with timeless style. V-neckline, a fitted waist with back waist elastic gathering, and a softly flowing tiered skirt.\r\n\r\nFeatures\r\n\r\nElegant all over paisley print.\r\nLong puff sleeves with elastic cuffs.\r\nSoft gathered shoulder detail.\r\nSuitable for casual outings, office wear, brunches, dinner dates, and special occasions.\r\nFit & Model Details: Regular Fit, Model Height 5\' 6\" wearing size M\r\n\r\nPlease bear in mind that the photo may be slightly different from the actual item in terms of colour due to lighting conditions or the display used to view',3195.00,2860.00,NULL,NULL,NULL,52,5,'archived',1,0.00,10,27,1,'2026-08-08 08:57:31','2026-08-08 08:57:31'),(50,'Tendenza Textured Oversized Tussle Top','Top\r\n3/4 Sleeve\r\nOversized\r\nCasual Wear\r\nMaterial : Woven\r\nMaterial Composition : 100% Polyester\r\nModel Height 5\' 6\" wearing size M \r\n\r\nDesigned with a relaxed fit, gathered yoke detailing, and voluminous three quarter sleeves, it offers the perfect balance of comfort and feminine style. The decorative tassel tie at the neckline adds a bohemian inspired touch.\r\n\r\nFeatures\r\n\r\nRound neckline with decorative tassel tie.\r\nGathered front yoke for added volume.\r\nThree quarter balloon sleeves with cuffs.\r\nPerfect for casual outings, weekend wear, vacations, and everyday styling.\r\nFit & Model Details: Relaxed Fit, Model Height 5\' 6\" wearing size M\r\n\r\nPlease bear in mind that the photo may be slightly different from the actual item in terms of colour due to lighting conditions or the display used to view',1590.00,1190.00,NULL,NULL,NULL,31,5,'archived',1,0.00,9,7,1,'2026-08-08 08:57:31','2026-08-08 08:57:31'),(51,'Tendenza Elegant Wide Leg Tailored Pant','test',2000.00,1800.00,NULL,NULL,NULL,75,5,'archived',0,0.00,2,0,1,'2026-08-08 08:57:31','2026-08-08 08:57:31'),(52,'test','ggwp',1000.00,800.00,NULL,NULL,NULL,9,5,'archived',1,0.00,0,0,1,'2026-08-08 08:57:31','2026-08-08 08:57:31'),(53,'test','',3050.00,2600.00,NULL,NULL,NULL,30,5,'archived',0,0.00,0,0,1,'2026-08-08 08:57:31','2026-08-08 08:57:31'),(54,'test','',3050.00,2600.00,NULL,NULL,NULL,30,5,'archived',0,0.00,0,0,1,'2026-08-08 08:57:31','2026-08-08 08:57:31'),(55,'test','',3050.00,2600.00,NULL,NULL,NULL,30,5,'archived',0,0.00,0,0,1,'2026-08-08 08:57:31','2026-08-08 08:57:31'),(56,'test','',3050.00,2600.00,NULL,NULL,NULL,30,5,'archived',0,0.00,0,0,1,'2026-08-08 08:57:31','2026-08-08 08:57:31'),(57,'test','',3050.00,2600.00,NULL,NULL,NULL,35,5,'archived',0,0.00,4,0,1,'2026-08-08 08:57:31','2026-08-08 08:57:31'),(58,'test','',3050.00,2600.00,NULL,NULL,NULL,30,5,'archived',0,0.00,0,0,1,'2026-08-08 08:57:31','2026-08-08 08:57:31'),(59,'test','',3050.00,2600.00,NULL,NULL,NULL,30,5,'a