INSERT INTO `whatsapp_chat_log` VALUES (4,'216960323305647','incoming','Hi',NULL,NULL,'customer','2026-08-08 15:23:15'),(5,'216960323305647','outgoing','ආයුබෝවන්! මම FelliRo හි Fashion Consultant ශාශා. 💕 \n\nඅද ඔබට මොනවගේ ලස්සන ඇඳුම්ද බලන්න ඕනේ? අපේ ලස්සන Crop Tops, Frocks, Co-ord Sets සහ තවත් බොහෝ දේ අප සතුව තියෙනවා. අපේ සම්පූර්ණ එකතුව සහ සියලුම නිර්මාණ https://felliro.com/products වෙබ් අඩවිය හරහාත් ඔබට පහසුවෙන්ම බලාගන්න පුළුවන්. \n\nකීවොත් මම ඔබට ගැලපෙන ලස්සනම ඩිසයින් ටිකක් පෙන්වන්නම්!',NULL,NULL,'bot','2026-08-08 15:23:17'),(6,'216960323305647','incoming','I want to order a croptop',NULL,NULL,'customer','2026-08-08 15:23:58'),(7,'216960323305647','outgoing','Wonderful choice! 💕 FelliRo එකේ අප සතුව අතිශයින්ම ලස්සන Crop Top ඩිසයින් 23ක්ම තියෙනවා (Price: Rs. 2800.00 each). \n\nඅපේ සම්පූර්ණ එකතුව සහ සියලුම ඩිසයින්ස් ඔබට https://felliro.com/products හරහා පහසුවෙන්ම බලාගන්න පුළුවන්. \n\nමම දැන් අපේ Crop Top එකතුවක פոտෝස් ටිකක් ඔයාව වෙත එවන්නම්. මේකෙන් ඔයාට කැමති ඩිසයින් එකක් තෝරගන්න පුළුවන්! ✨',NULL,NULL,'bot','2026-08-08 15:23:59'),(8,'216960323305647','outgoing','✨ *[ID:61] Crop Top 1*\n💰 *Rs. 2800.00*\n🎨 Colors: Brown, White, Black, Pink\n📏 Sizes: Free\n📦 In Stock: 20','/uploads/product-1785670406249-583190102.png','image','bot','2026-08-08 15:24:00'),(9,'216960323305647','outgoing','✨ *[ID:62] Crop Top 2*\n💰 *Rs. 2800.00*\n🎨 Colors: Pink, Brown, Navy Blue, White\n📏 Sizes: Free\n📦 In Stock: 20','/uploads/product-1785685009201-609684462.png','image','bot','2026-08-08 15:24:02'),(10,'216960323305647','outgoing','✨ *[ID:63] Crop Top 3*\n💰 *Rs. 2800.00*\n🎨 Colors: White, Pink, Black\n📏 Sizes: Free\n📦 In Stock: 10','/uploads/product-1785685163077-771110396.png','image','bot','2026-08-08 15:24:03'),(11,'216960323305647','outgoing','✨ *[ID:64] Crop Top 4*\n💰 *Rs. 2800.00*\n🎨 Colors: Blue, White, Black\n📏 Sizes: Free\n📦 In Stock: 13','/uploads/product-1785685340369-262333286.png','image','bot','2026-08-08 15:24:05'),(12,'216960323305647','outgoing','✨ *[ID:65] Crop Top 5*\n💰